-- PRIORITY 1 — pool hydrator (perpetual; re-queues itself)
INSERT INTO task_pool (task_name, prompt, category, instance_target, priority, estimated_minutes) VALUES
('pool-hydrator', 'Keep the FORTRESS pool at >=15 waiting tasks, focused entirely on security and identity hardening for a SOLO operator who is the sole Google Workspace admin with a Cloudflare-purchased domain. Check depth: SELECT COUNT(*) FROM task_pool WHERE instance_target=''fortress'' AND status=''waiting''. If <15, generate 10 new IMPLEMENTATION tasks (not research) across: account/identity hardening, MFA/hardware keys, Advanced Protection, DMARC/SPF/DKIM enforcement, Cloudflare DNS security (DNSSEC, registrar lock, proxy status), OAuth app audits, secrets management/rotation, recovery runbooks, and periodic re-audits (re-check DMARC RUA reports, re-review OAuth grants monthly). Never generate a task that weakens a control. Priority 10-40. Insert them, then re-queue yourself: INSERT INTO task_pool (task_name,prompt,category,instance_target,priority,estimated_minutes) VALUES (''pool-hydrator'',<this prompt verbatim>,''meta'',''fortress'',1,8). Log: INSERT INTO events (event_type,source,payload) VALUES (''pool.hydrated'',''fortress'',json_object(''tasks_added'',?,''depth_after'',?)).', 'meta', 'fortress', 1, 8);

-- TASK POOL (13 tasks)
INSERT INTO task_pool (task_name, prompt, category, instance_target, priority, estimated_minutes) VALUES
('break-glass-admin', 'Eliminate the single-super-admin lockout risk. Google recommends 2-4 super admins, never 1. Create a dedicated break-glass super-admin account (not the daily driver): strong unique passphrase in a password manager, a hardware security key enrolled, offline recovery codes printed and stored physically. Write a runbook documenting when/how to use it. This account is used ONLY for emergency recovery. Document the whole thing in a secure note. Do NOT store the password in plaintext in any repo.', 'identity', 'fortress', 10, 20),
('mfa-enforce-kill-sms', 'Enforce MFA/2SV across every account in the Workspace with no exceptions. Remove SMS as an allowed factor (SIM-swap risk) in favor of authenticator apps and hardware security keys. In Admin console: Security > Authentication > 2-Step Verification, enforce, set allowed methods to ''Any except verification codes via text/call'' or stricter. Document the enforced policy.', 'identity', 'fortress', 12, 18),
('advanced-protection-enroll', 'Enroll the primary admin and any high-privilege account in Google''s Advanced Protection Program (APP). APP enforces phishing-resistant security keys, blocks untrusted third-party app access, and tightens account recovery against hijacking. Requires 2 security keys (primary + backup). Document enrollment and which accounts are covered.', 'identity', 'fortress', 14, 15),
('admin-daily-separation', 'Separate the super-admin identity from the daily-driver identity. The account used for email/docs/day-to-day should be a standard user; a distinct account holds super-admin rights and is used only for admin tasks. Migrate daily use off the admin account. Document the two-account model and the rule: never browse/email from the super-admin account.', 'identity', 'fortress', 16, 20),
('dmarc-stage1-none-rua', 'Begin DMARC rollout at monitoring stage. Publish a DMARC TXT record at _dmarc.<domain> in Cloudflare DNS (DNS-only / grey cloud) with p=none and a rua= mailbox for aggregate reports. This observes without blocking. Confirm the record resolves. Note: DMARC is mandatory in 2026 (Google/Yahoo/MS reject non-compliant mail). Document the record and where reports land.', 'email-auth', 'fortress', 20, 15),
('spf-flatten', 'Fix SPF before enforcing DMARC. Audit the SPF TXT record for the >10 DNS-lookup limit (a common DMARC-fail cause). Flatten includes where needed, ensure Google Workspace is authorized (include:_spf.google.com), end with ~all (soft) moving toward -all. Verify with an SPF checker. Document the final record.', 'email-auth', 'fortress', 22, 18),
('dkim-all-senders', 'Enable DKIM for every sender of your domain. In Google Admin: Apps > Google Workspace > Gmail > Authenticate email, generate the DKIM key (2048-bit), publish the provided TXT record in Cloudflare DNS (DNS-only), then start authentication. Do the same for any other service that sends as your domain. Verify DKIM passes. Document keys and selectors.', 'email-auth', 'fortress', 24, 18),
('dmarc-stage2-quarantine', 'Advance DMARC to quarantine ONLY after SPF is flattened, DKIM is live on all senders, and RUA reports show clean alignment for legit mail. Update _dmarc record to p=quarantine (optionally pct=25 then ramp to 100). Keep monitoring RUA. Gate: do not run if any legitimate sender still fails alignment — mark this task failed with reason ''alignment_not_clean'' and requeue.', 'email-auth', 'fortress', 30, 12),
('dmarc-stage3-reject', 'Final DMARC lockdown. After a clean period at p=quarantine with no legitimate mail being quarantined, update _dmarc to p=reject. This blocks all unauthorized mail from your domain at the receiver''s SMTP layer. Keep rua reporting on. Gate: only proceed if quarantine stage showed zero legit-mail failures — otherwise fail with ''not_ready_for_reject'' and requeue.', 'email-auth', 'fortress', 35, 12),
('cloudflare-dns-hardening', 'Harden the Cloudflare DNS zone. Enable DNSSEC (add the DS record at the registrar). Turn on registrar/domain lock to prevent transfers. Audit every record: verification/MX/SPF/DKIM/DMARC TXT must be DNS-only (grey cloud — orange proxy breaks mail + Google verification); web records proxied (orange) as appropriate. Remove stale records. Document the full zone and the grey/orange rationale per record.', 'dns', 'fortress', 26, 20),
('oauth-app-audit', 'Audit third-party OAuth access (2026 OAuth-exploitation threat). In Admin console: Security > API controls > review app access. List every app with Workspace scopes, flag over-scoped or unused grants, revoke stale ones, set trusted/limited/blocked policies. Restrict access to unconfigured third-party apps by default. Document what was revoked and the resulting policy.', 'identity', 'fortress', 28, 18),
('secrets-inventory-rotate', 'Inventory every API key/token/credential across the stack (Cloudflare, Google, Slack, Discord, GitHub, any worker). Move all of them out of source/config into secret stores: Cloudflare via `wrangler secret put`, Google via Secret Manager. Rotate anything that ever touched a repo or plaintext. Establish and document a rotation cadence. Confirm no secret remains in any committed file (grep the repo history conceptually).', 'secrets', 'fortress', 32, 25),
('recovery-runbook', 'Write the master recovery runbook and store it offline (printed + encrypted copy). Cover: super-admin lockout recovery, break-glass account use, hardware-key loss, domain/DNS compromise, secret leak response, and the Google account-recovery process timeline. Include every account, where recovery codes live, and emergency contacts. This is the document you reach for on your worst day.', 'resilience', 'fortress', 38, 20);

